window.AUTH=window.AUTH||{};window.AUTH["17-773"]={"d":"17-773","id":"2018/17-773","n":"Culbertson v. Berryhill","briefs":[{"k":"petitioner","label":"Brief of petitioner Richard Culbertson","date":"2018-07-16","url":"https://www.supremecourt.gov/DocketPDF/17/17-773/54301/20180716130124603_17-773%20Apellants%20Brief.pdf","side":"pet","n":34},{"k":"respondent","label":"Brief of respondent Nancy A. Berryhill, Deputy Commissioner for Operations, Social Security Administration in support of reversal and remand","date":"2018-07-16","url":"https://www.supremecourt.gov/DocketPDF/17/17-773/54403/20180716170642175_17-773tsUnitedStates.pdf","side":"res","n":52},{"k":"reply","label":"Reply of petitioner Richard Culbertson","date":"2018-10-09","url":"https://www.supremecourt.gov/DocketPDF/17/17-773/66257/20181009153714545_17-773_Reply%20Brief.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-773_4h25.pdf","tr":true,"items":[{"t":"case","label":"Bookman v. Commissioner of Soc. Sec.","cite":"490 F. Appx. 314","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20Appx./490/314/","by":{"0":"5"},"q":[{"src":"brief","b":0,"text":"effectively increases the portion of past-due benefits the successful Social Security claimant may pocket.","cite":"490 F. Appx. 314"}]},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"by":{"0":"6"},"q":[{"src":"brief","b":0,"text":"must apply the statute according to its terms.","cite":"555 U.S. 379, 387"}]},{"t":"case","label":"Caminetti v. United States","cite":"242 U.S. 470","y":1917,"id":"scdb/1916-190","sc":1,"by":{"0":"11"},"q":[{"src":"brief","b":0,"text":"the meaning of a statute must, in the first instance, be sought in the language in which the act is framed, and if that is plain * * * the sole function of the courts is to enforce it according to its terms.","cite":"242 U.S. 470, 485"}]},{"t":"case","label":"Clark v. Astrue","cite":"529 F.3d 1211","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/529/1211/","by":{"0":"15","1":"22","2":"17"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"0":"12, 13, 18"},"q":[{"src":"brief","b":0,"text":"presume that a legislature says in a statute what it means and means in a statute what it says there.","cite":"503 U.S. 249, 253254"}]},{"t":"case","label":"Crawford v. Astrue","cite":"586 F.3d 1142","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/586/1142/","by":{"0":"24","2":"16"},"q":[{"src":"brief","b":0,"text":"future benefits * * * may far exceed the past-due benefits awarded.","cite":"586 F.3d 1142, 1150"}]},{"t":"case","label":"Dawson v. Finch","cite":"425 F.2d 1192","y":1970,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/425/1192/","by":{"0":"4, 27","1":"13, 19, 20"},"q":[{"src":"brief","b":1,"text":"‘preclud[es] the aggregate allowance of attorney’s fees greater than 25 percent of the [claimant’s] past due benefits.’","cite":"425 F.2d at 1195"},{"src":"argument","who":"Ms. Weil","text":"And, in fact, if I could, Your Honors, I found the brief where they wrote in Dawson to explain their position, which has been maintained for 50 years, for half a century: \"The most of the benefits provided for by the Act are intended to supply a means of livelihood to persons who have been deprived of their ability to support themselves, e.g., old age benefits for retirees and disability benefits for the disabled."},{"src":"argument","who":"Ms. Weil","text":"I'm reading from the brief of the government in Dawson. So that was in 1970. Then, in Gisbrecht, the solicitor said that \"the statute's primary goal is ensuring the claimant keeps as much of the back-due award as possible.\" And then later said -- quoted an Eleventh Circuit case, Kay versus Apfel, in the same brief in this Court, that \"406(b) is designed to protect a particularly vulnerable class of claimants."}]},{"t":"case","label":"Department of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"id":"2014/13-894","sc":1,"by":{"0":"12"},"q":[{"src":"brief","b":0,"text":"Congress generally acts intentionally when it uses particular language in one section of a statute but omits it in another.","cite":"135 S. Ct. 913, 919"}]},{"t":"case","label":"Gisbrecht v. Barnhart","cite":"535 U.S. 789","y":2002,"id":"2001/01-131","sc":1,"by":{"0":"passim","1":"2, 3, 8, 13, 14, 25","2":"20"},"q":[{"src":"brief","b":0,"text":"refun[d] to the claimant the amount of the smaller fee,","cite":"535 U.S. at 796"},{"src":"brief","b":0,"text":"virtually every attorney representing Title II disability claimants includes in his/her retainer agreement a provision calling for a fee equal to 25% of the past-due benefits.","cite":"535 U.S. at 803"},{"src":"brief","b":1,"text":"to obtain higher fee awards under [Section] 406(b).","cite":"535 U.S. at 798 n.6"},{"src":"brief","b":1,"text":"[Section] 406(b) calls for court review of such arrangements as an independent check, to assure that they yield reasonable results in particular cases.","cite":"535 U.S. at 807"},{"src":"brief","b":2,"text":"[c]ollecting or even demanding from the client anything more than the authorized allocation of pastdue benefits is a criminal offense.","cite":"535 U.S. 789, 796"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"§406(a) governs fees for representation in administrative proceedings; §406(b) controls fees for representation in court.","cite":"535 U. S. 789, 794"},{"src":"argument","who":"Mr. Ortiz","text":"Also, Your Honors, the structure of the Act makes this clear. In Gisbrecht, this Court defined -- said that the statute handles discretely claims for work before the agency and claims before the court."},{"src":"argument","who":"Mr. Ortiz","text":"In Gisbrecht, Your Honor, it -- the concurrence mentioned that it was 41 percent. It's our understanding that more up-to-date statistics are above 40 percent to 50 percent, somewhere in there."},{"src":"argument","who":"Mr. Yang","text":"So that anomaly suggests that our reading of a 25 percent aggregate cap for the judicial proceedings is what was intended by Congress in 406(b), which would then suggest that normally, although there's not always -- it's not always the case because sometimes agency fees can exceed 25 percent of past-due benefits, normally, it should not exceed 50 percent, and in many cases, where the courts -- where you've got a lot of benefits, as the Court recognized in Gisbrecht, the reasonableness criterion allows courts to police for windfall --"}]},{"t":"case","label":"Morris v. Social Sec. Admin.","cite":"689 F.2d 495","y":1982,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/689/495/","by":{"0":"27","1":"19, 21"},"q":[{"src":"argument","who":"Justice Sotomayor","text":"The retained amount. Don't you think that Congress wouldn't have wanted Social Security recipients to be hounded by collection efforts?"},{"src":"argument","who":"Justice Ginsburg","text":"Practically -- practically, where would you -- you can't get money out of the Social Security benefits, if -- if they've been exhausted under -- under (b) for the court work."},{"src":"argument","who":"Justice Ginsburg","text":"Well, wouldn't that -- if that's the general case, then what are the practical consequences of our agreeing with your position when you can't get more than 25 percent out of the Social Security benefits themselves?"}]},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"by":{"0":"10, 27"},"q":[{"src":"brief","b":0,"text":"need not consider [any] extra-textual evidence,","cite":"137 S. Ct. 929, 942"}]},{"t":"case","label":"Paltan v. Commissioner of Soc. Sec.","cite":"518 F. Appx. 673","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20Appx./518/673/","by":{"0":"5"},"q":[{"src":"brief","b":0,"text":"effectively increases the portion of past-due benefits the successful Social Security claimant may pocket.","cite":"518 F. Appx. 673"}]},{"t":"case","label":"Parrish v. Commissioner of Soc. Sec. Admin.","cite":"698 F.3d 1215","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/698/1215/","by":{"0":"3, 4"},"q":[{"src":"brief","b":0,"text":"requires the government to pay the fees and expenses of a ‘prevailing party’ [in a civil proceeding] unless the government’s position was ‘substantially justified.’","cite":"698 F.3d 1215, 1218"}]},{"t":"case","label":"Rubin v. United States","cite":"449 U.S. 424","y":1981,"id":"1980/79-1013","sc":1,"by":{"0":"13, 27"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"12","1":"17"},"q":[{"src":"brief","b":1,"text":"Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"464 U.S. 16, 23"}]},{"t":"case","label":"State Farm Fire & Cas. Co. v. United States ex rel. Rigsby","cite":"137 S. Ct. 436","y":2016,"id":"2016/15-513","sc":1,"by":{"0":"10"}},{"t":"case","label":"Washington State Dep’t of Soc. & Health Servs. v. Guardianship Estate of Keffeler","cite":"537 U.S. 371","y":2003,"id":"2002/01-1420","sc":1,"by":{"0":"16","1":"9","2":"21"},"q":[{"src":"brief","b":0,"text":"warrant respect in closing the door on any suggestion that the usual rules of statutory construction should get short shrift.","cite":"537 U.S. 371, 385"},{"src":"brief","b":1,"text":"publicly available operating instructions for processing Social Security claims.","cite":"537 U.S. 371, 385"},{"src":"brief","b":2,"text":"the publicly available operating instructions for processing Social Security claims,","cite":"537 U.S. 371, 385"},{"src":"brief","b":2,"text":"[w]hile [POMS] interpretations are not products of formal rulemaking, they nevertheless warrant respect in closing the door on any suggestion that the usual rules of statutory construction should get short shrift.","cite":"537 U.S. at 385"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","subs":["(d)(1)(A)","(d)","(d)(2)(A)"],"stext":{"head":"§2412. Costs and fees","paras":[[0,"(a)(1) Except as otherwise specifically provided by statute, a judgment for costs, as enumerated in section 1920 of this title, but not including the fees and expenses of attorneys, may be awarded to the prevailing party in any civil action brought by or against the United States or any agency or any official of the United States acting in his or her official capacity in any court having jurisdiction of such action. A judgment for costs when taxed against the United States shall, in an amount established by statute, court rule, or order, be limited to reimbursing in whole or in part the prevailing party for the costs incurred by such party in the litigation."],[0,"(2) A judgment for costs, when awarded in favor of the United States in an action brought by the United States, may include an amount equal to the filing fee prescribed under section 1914(a) of this title. The preceding sentence shall not be construed as requiring the United States to pay any filing fee."],[0,"(b) Unless expressly prohibited by statute, a court may award reasonable fees and expenses of attorneys, in addition to the costs which may be awarded pursuant to subsection (a), to the prevailing party in any civil action brought by or against the United States or any agency or any official of the United States acting in his or her official capacity in any court having jurisdiction of such action. The United States shall be liable for such fees and expenses to the same extent that any other party would be liable under the common law or under the terms of any statute which specifically provides for such an award."],[0,"(c)(1) Any judgment against the United States or any agency and any official of the United States acting in his or her official capacity for costs pursuant to subsection (a) shall be paid as provided in sections 2414 and 2517 of this title and shall be in addition to any relief provided in the judgment."],[0,"(2) Any judgment against the United States or any agency and any official of the United States acting in his or her official capacity for fees and expenses of attorneys pursuant to subsection (b) shall be paid as provided in sections 2414 and 2517 of this title, except that if the basis for the award is a finding that the United States acted in bad faith, then the award shall be paid by any agency found to have acted in bad faith and shall be in addition to any relief provided in the judgment."],[0,"(d)(1)(A) Except as otherwise specifically provided by statute, a court shall award to a prevailing party other than the United States fees and other expenses, in addition to any costs awarded pursuant to subsection (a), incurred by that party in any civil action (other than cases sounding in tort), including proceedings for judicial review of agency action, brought by or against the United States in any court having jurisdiction of that action, unless the court finds that the position of the United States was substantially justified or that special circumstances make an award unjust."],[0,"(B) A party seeking an award of fees and other expenses shall, within thirty days of final judgment in the action, submit to the court an application for fees and other expenses which shows that the party is a prevailing party and is eligible to receive an award under this subsection, and the amount sought, including an itemized statement from any attorney or expert witness representing or appearing in behalf of the party stating the actual time expended and the rate at which fees and other expenses were computed. The party shall also allege that the position of the United States was not substantially justified. Whether or not the position of the United States was substantially justified shall be determined on the basis of the record (including the record with respect to the action or failure to act by the agency upon which the civil action is based) which is made in the civil action for which fees and other expenses are sought."],[0,"(C) The court, in its discretion, may reduce the amount to be awarded pursuant to this subsection, or deny an award, to the extent that the prevailing party during the course of the proceedings engaged in conduct which unduly and unreasonably protracted the final resolution of the matter in controversy."],[0,"(D) If, in a civil action brought by the United States or a proceeding for judicial review of an adversary adjudication described in section 504(a)(4) of title 5, the demand by the United States is substantially in excess of the judgment finally obtained by the United States and is unreasonable when compared with such judgment, under the facts and circumstances of the case, the court shall award to the party the fees and other expenses related to defending against the excessive demand, unless the party has committed a willful violation of law or otherwise acted in bad faith, or special circumstances make an award unjust. Fees and expenses awarded under this subparagraph shall be paid only as a consequence of appropriations provided in advance."],[0,"(2) For the purposes of this subsection—"],[1,"(A) \"fees and other expenses\" includes the reasonable expenses of expert witnesses, the reasonable cost of any study, analysis, engineering report, test, or project which is found by the court to be necessary for the preparation of the party's case, and reasonable attorney fees (The amount of fees awarded under this subsection shall be based upon prevailing market rates for the kind and quality of the services furnished, except that (i) no expert witness shall be compensated at a rate in excess of the highest rate of compensation for expert witnesses paid by the United States; and (ii) attorney fees shall not be awarded in excess of $125 per hour unless the court determines that an increase in the cost of living or a special factor, such as the limited availability of qualified attorneys for the proceedings involved, justifies a higher fee.);"],[1,"(B) \"party\" means (i) an individual whose net worth did not exceed $2,000,000 at the time the civil action was filed, or (ii) any owner of an unincorporated business, or any partnership, corporation, association, unit of local government, or organization, the net worth of which did not exceed $7,000,000 at the time the civil action was filed, and which had not more than 500 employees at the time the civil action was filed; except that an organization described in section 501(c)(3) of the Internal Revenue Code of 1986 (26 U.S.C. 501(c)(3)) exempt from taxation under section 501(a) of such Code, or a cooperative association as defined in section 15(a) of the Agricultural Marketing Act (12 U.S.C. 1141j(a)), may be a party regardless of the net worth of such organization or cooperative association or for purposes of subsection (d)(1)(D), a small entity as defined in section 601 of title 5;"],[1,"(C) \"United States\" includes any agency and any official of the United States acting in his or her official capacity;"],[1,"(D) \"position of the United States\" means, in addition to the position taken by the United States in the civil action, the action or failure to act by the agency upon which the civil action is based; except that fees and expenses may not be awarded to a party for any portion of the litigation in which the party has unreasonably protracted the proceedings;"],[1,"(E) \"civil action brought by or against the United States\" includes an appeal by a party, other than the United States, from a decision of a contracting officer rendered pursuant to a disputes clause in a contract with the Government or pursuant to chapter 71 of title 41;"],[1,"(F) \"court\" includes the United States Court of Federal Claims and the United States Court of Appeals for Veterans Claims;"],[1,"(G) \"final judgment\" means a judgment that is final and not appealable, and includes an order of settlement;"],[1,"(H) \"prevailing party\", in the case of eminent domain proceedings, means a party who obtains a final judgment (other than by settlement), exclusive of interest, the amount of which is at least as close to the highest valuation of the property involved that is attested to at trial on behalf of the property owner as it is to the highest valuation of the property involved that is attested to at trial on behalf of the Government; and"],[1,"(I) \"demand\" means the express demand of the United States which led to the adversary adjudication, but shall not include a recitation of the maximum statutory penalty (i) in the complaint, or (ii) elsewhere when accompanied by an express demand for a lesser amount."],[0,"(3) In awarding fees and other expenses under this subsection to a prevailing party in any action for judicial review of an adversary adjudication, as defined in subsection (b)(1)(C) of section 504 of title 5, or an adversary adjudication subject to chapter 71 of title 41, the court shall include in that award fees and other expenses to the same extent authorized in subsection (a) of such section, unless the court finds that during such adversary adjudication the position of the United States was substantially justified, or that special circumstances make an award unjust."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2412?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3","1":"2, 2, 2, 2","2":"16"}},{"t":"usc","label":"42 U.S.C. § 306","url":"https://www.law.cornell.edu/uscode/text/42/306","subs":["(a)"],"by":{"0":"20"}},{"t":"usc","label":"42 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/42/401","stext":{"head":"§401. Trust Funds","paras":[[0,"(a) Federal Old-Age and Survivors Insurance Trust Fund"],[0,"There is hereby created on the books of the Treasury of the United States a trust fund to be known as the \"Federal Old-Age and Survivors Insurance Trust Fund\". The Federal Old-Age and Survivors Insurance Trust Fund shall consist of the securities held by the Secretary of the Treasury for the Old-Age Reserve Account and the amount standing to the credit of the Old-Age Reserve Account on the books of the Treasury on January 1, 1940, which securities and amount the Secretary of the Treasury is authorized and directed to transfer to the Federal Old-Age and Survivors Insurance Trust Fund, and, in addition, such gifts and bequests as may be made as provided in subsection (i)(1), and such amounts as may be appropriated to, or deposited in, the Federal Old-Age and Survivors Insurance Trust Fund as hereinafter provided. There is hereby appropriated to the Federal Old-Age and Survivors Insurance Trust Fund for the fiscal year ending June 30, 1941, and for each fiscal year thereafter, out of any moneys in the Treasury not otherwise appropriated, amounts equivalent to 100 per centum of—"],[1,"(1) the taxes (including interest, penalties, and additions to the taxes) received under subchapter A of chapter 9 of the Internal Revenue Code of 1939 (and covered into the Treasury) which are deposited into the Treasury by collectors of internal revenue before January 1, 1951; and"],[1,"(2) the taxes certified each month by the Commissioner of Internal Revenue as taxes received under subchapter A of chapter 9 of such Code which are deposited into the Treasury by collectors of internal revenue after December 31, 1950, and before January 1, 1953, with respect to assessments of such taxes made before January 1, 1951; and"],[1,"(3) the taxes imposed by subchapter A of chapter 9 of such Code with respect to wages (as defined in section 1426 of such Code), and by chapter 21 (other than sections 3101(b) and 3111(b)) of the Internal Revenue Code of 1954 with respect to wages (as defined in section 3121 of such Code) reported to the Commissioner of Internal Revenue pursuant to section 1420(c) of the Internal Revenue Code of 1939 after December 31, 1950, or to the Secretary of the Treasury or his delegates pursuant to subtitle F of the Internal Revenue Code of 1954 after December 31, 1954, as determined by the Secretary of the Treasury by applying the applicable rates of tax under such subchapter or chapter 21 (other than sections 3101(b) and 3111(b)) to such wages, which wages shall be certified by the Commissioner of Social Security on the basis of the records of wages established and maintained by such Commissioner in accordance with such reports, less the amounts specified in clause (1) of subsection (b) of this section; and"],[1,"(4) the taxes imposed by subchapter E of chapter 1 of the Internal Revenue Code of 1939, with respect to self-employment income (as defined in section 481 of such Code), and by chapter 2 (other than section 1401(b)) of the Internal Revenue Code of 1954 with respect to self-employment income (as defined in section 1402 of such Code) reported to the Commissioner of Internal Revenue on tax returns under such subchapter or to the Secretary of the Treasury or his delegate on tax returns under subtitle F of such Code, as determined by the Secretary of the Treasury by applying the applicable rate of tax under such subchapter or chapter (other than section 1401(b)) to such self-employment income, which self-employment income shall be certified by the Commissioner of Social Security on the basis of the records of self-employment income established and maintained by the Commissioner of Social Security in accordance with such returns, less the amounts specified in clause (2) of subsection (b) of this section."],[0,"The amounts appropriated by clauses (3) and (4) of this subsection shall be transferred from time to time from the general fund in the Treasury to the Federal Old-Age and Survivors Insurance Trust Fund, and the amounts appropriated by clauses (1) and (2) of subsection (b) shall be transferred from time to time from the general fund in the Treasury to the Federal Disability Insurance Trust Fund, such amounts to be determined on the basis of estimates by the Secretary of the Treasury of the taxes, specified in clauses (3) and (4) of this subsection, paid to or deposited into the Treasury; and proper adjustments shall be made in amounts subsequently transferred to the extent prior estimates were in excess of or were less than the taxes specified in such clauses (3) and (4) of this subsection. All amounts transferred to either Trust Fund under the preceding sentence shall be invested by the Managing Trustee in the same manner and to the same extent as the other assets of such Trust Fund. Notwithstanding the preceding sentence, in any case in which the Secretary of the Treasury determines that the assets of either such Trust Fund would otherwise be inadequate to meet such Fund's obligations for any month, the Secretary of the Treasury shall transfer to such Trust Fund on the first day of such month the amount which would have been transferred to such Fund under this section as in effect on October 1, 1990; and such Trust Fund shall pay interest to the general fund on the amount so transferred on the first day of any month at a rate (calculated on a daily basis, and applied against the difference between the amount so transferred on such first day and the amount which would have been transferred to the Trust Fund up to that day under the procedures in effect on January 1, 1983) equal to the rate earned by the investments of such Fund in the same month under subsection (d)."],[0,"(b) Federal Disability Insurance Trust Fund"],[0,"There is hereby created on the books of the Treasury of the United States a trust fund to be known as the \"Federal Disability Insurance Trust Fund\". The Federal Disability Insurance Trust Fund shall consist of such gifts and bequests as may be made as provided in subsection (i)(1), and such amounts as may be appropriated to, or deposited in, such fund as provided in this section. There is hereby appropriated to the Federal Disability Insurance Trust Fund for the fiscal year ending June 30, 1957, and for each fiscal year thereafter, out of any moneys in the Treasury not otherwise appropriated, amounts equivalent to 100 per centum of—"],[1,"(1)(A) ½ of 1 per centum of the wages (as defined in section 3121 of the Internal Revenue Code of 1954) paid after December 31, 1956, and before January 1, 1966, and reported to the Secretary of the Treasury or his delegate pursuant to subtitle F of the Internal Revenue Code of 1954, (B) 0.70 of 1 per centum of the wages (as so defined) paid after December 31, 1965, and before January 1, 1968, and so reported, (C) 0.95 of 1 per centum of the wages (as so defined) paid after December 31, 1967, and before January 1, 1970, and so reported, (D) 1.10 per centum of the wages (as so defined) paid after December 31, 1969, and before January 1, 1973, and so reported, (E) 1.1 per centum of the wages (as so defined) paid after December 31, 1972, and before January 1, 1974, and so reported, (F) 1.15 per centum of the wages (as so defined) paid after December 31, 1973, and before January 1, 1978, and so reported, (G) 1.55 per centum of the wages (as so defined) paid after December 31, 1977, and before January 1, 1979, and so reported, (H) 1.50 per centum of the wages (as so defined) paid after December 31, 1978, and before January 1, 1980, and so reported, (I) 1.12 per centum of the wages (as so defined) paid after December 31, 1979, and before January 1, 1981, and so reported, (J) 1.30 per centum of the wages (as so defined) paid after December 31, 1980, and before January 1, 1982, and so reported, (K) 1.65 per centum of the wages (as so defined) paid after December 31, 1981, and before January 1, 1983, and so reported, (L) 1.25 per centum of the wages (as so defined) paid after December 31, 1982, and before January 1, 1984, and so reported, (M) 1.00 per centum of the wages (as so defined) paid after December 31, 1983, and before January 1, 1988, and so reported, (N) 1.06 per centum of the wages (as so defined) paid after December 31, 1987, and before January 1, 1990, and so reported, (O) 1.20 per centum of the wages (as so defined) paid after December 31, 1989, and before January 1, 1994, and so reported, (P) 1.88 per centum of the wages (as so defined) paid after December 31, 1993, and before January 1, 1997, and so reported, (Q) 1.70 per centum of the wages (as so defined) paid after December 31, 1996, and before January 1, 2000, and so reported, (R) 1.80 per centum of the wages (as so defined) paid after December 31, 1999, and before January 1, 2016, and so reported, (S) 2.37 per centum of the wages (as so defined) paid after December 31, 2015, and before January 1, 2019, and so reported, and (T) 1.80 per centum of the wages (as so defined) paid after December 31, 2018, and so reported,,1 which wages shall be certified by the Commissioner of Social Security on the basis of the records of wages established and maintained by such Commissioner in accordance with such reports; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/401?type=usc&year=mostrecent&link-type=html"},"by":{"0":"1","1":"passim"}},{"t":"usc","label":"42 U.S.C. § 406","url":"https://www.law.cornell.edu/uscode/text/42/406","subs":["(a)","(a)(1)","(a)(2)(A)","(a)(2)(C)","(a)(3)(A)(1)","(b)","(b)(1)(A)","(a)(1976)","(a)(2)","(a)(2)(A)(ii)","(a)(2)(A)(ii)(II)","(a)(2)(A)(iii)","(a)(3)","(a)(3)(A)","(a)(3)(A)(i)","(a)(3)(C)","(a)(4)","(a)(5)","(b)(1)","(b)(2)","(d)","(e)(1)"],"stext":{"head":"§406. Representation of claimants before Commissioner","paras":[[0,"(a) Recognition of representatives; fees for representation before Commissioner"],[0,"(1) The Commissioner of Social Security may prescribe rules and regulations governing the recognition of agents or other persons, other than attorneys as hereinafter provided, representing claimants before the Commissioner of Social Security, and may require of such agents or other persons, before being recognized as representatives of claimants that they shall show that they are of good character and in good repute, possessed of the necessary qualifications to enable them to render such claimants valuable service, and otherwise competent to advise and assist such claimants in the presentation of their cases. An attorney in good standing who is admitted to practice before the highest court of the State, Territory, District, or insular possession of his residence or before the Supreme Court of the United States or the inferior Federal courts, shall be entitled to represent claimants before the Commissioner of Social Security. Notwithstanding the preceding sentences, the Commissioner, after due notice and opportunity for hearing, (A) may refuse to recognize as a representative, and may disqualify a representative already recognized, any attorney who has been disbarred or suspended from any court or bar to which he or she was previously admitted to practice or who has been disqualified from participating in or appearing before any Federal program or agency, and (B) may refuse to recognize, and may disqualify, as a non-attorney representative any attorney who has been disbarred or suspended from any court or bar to which he or she was previously admitted to practice. A representative who has been disqualified or suspended pursuant to this section from appearing before the Social Security Administration as a result of collecting or receiving a fee in excess of the amount authorized shall be barred from appearing before the Social Security Administration as a representative until full restitution is made to the claimant and, thereafter, may be considered for reinstatement only under such rules as the Commissioner may prescribe. The Commissioner of Social Security may, after due notice and opportunity for hearing, suspend or prohibit from further practice before the Commissioner any such person, agent, or attorney who refuses to comply with the Commissioner's rules and regulations or who violates any provision of this section for which a penalty is prescribed. The Commissioner of Social Security may, by rule and regulation, prescribe the maximum fees which may be charged for services performed in connection with any claim before the Commissioner of Social Security under this subchapter, and any agreement in violation of such rules and regulations shall be void. Except as provided in paragraph (2)(A), whenever the Commissioner of Social Security, in any claim before the Commissioner for benefits under this subchapter, makes a determination favorable to the claimant, the Commissioner shall, if the claimant was represented by an attorney in connection with such claim, fix (in accordance with the regulations prescribed pursuant to the preceding sentence) a reasonable fee to compensate such attorney for the services performed by him in connection with such claim."],[0,"(2)(A) In the case of a claim of entitlement to past-due benefits under this subchapter, if—"],[1,"(i) an agreement between the claimant and another person regarding any fee to be recovered by such person to compensate such person for services with respect to the claim is presented in writing to the Commissioner of Social Security prior to the time of the Commissioner's determination regarding the claim,"],[1,"(ii) the fee specified in the agreement does not exceed the lesser of—"],[2,"(I) 25 percent of the total amount of such past-due benefits (as determined before any applicable reduction under section 1320a–6(a) of this title), or"],[2,"(II) $4,000, and"],[1,"(iii) the determination is favorable to the claimant,"],[0,"then the Commissioner of Social Security shall approve that agreement at the time of the favorable determination, and (subject to paragraph (3)) the fee specified in the agreement shall be the maximum fee. The Commissioner of Social Security may from time to time increase the dollar amount under clause (ii)(II) to the extent that the rate of increase in such amount, as determined over the period since January 1, 1991, does not at any time exceed the rate of increase in primary insurance amounts under section 415(i) of this title since such date. The Commissioner of Social Security shall publish any such increased amount in the Federal Register."],[0,"(B) For purposes of this subsection, the term \"past-due benefits\" excludes any benefits with respect to which payment has been continued pursuant to subsection (g) or (h) of section 423 of this title."],[0,"(C) In any case involving—"],[1,"(i) an agreement described in subparagraph (A) with any person relating to both a claim of entitlement to past-due benefits under this subchapter and a claim of entitlement to past-due benefits under subchapter XVI, and"],[1,"(ii) a favorable determination made by the Commissioner of Social Security with respect to both such claims,"],[0,"the Commissioner of Social Security may approve such agreement only if the total fee or fees specified in such agreement does not exceed, in the aggregate, the dollar amount in effect under subparagraph (A)(ii)(II)."],[0,"(D) In the case of a claim with respect to which the Commissioner of Social Security has approved an agreement pursuant to subparagraph (A), the Commissioner of Social Security shall provide the claimant and the person representing the claimant a written notice of—"],[1,"(i) the dollar amount of the past-due benefits (as determined before any applicable reduction under section 1320a–6(a) of this title) and the dollar amount of the past-due benefits payable to the claimant,"],[1,"(ii) the dollar amount of the maximum fee which may be charged or recovered as determined under this paragraph, and"],[1,"(iii) a description of the procedures for review under paragraph (3)."],[0,"(3)(A) The Commissioner of Social Security shall provide by regulation for review of the amount which would otherwise be the maximum fee as determined under paragraph (2) if, within 15 days after receipt of the notice provided pursuant to paragraph (2)(D)—"],[1,"(i) the claimant, or the administrative law judge or other adjudicator who made the favorable determination, submits a written request to the Commissioner of Social Security to reduce the maximum fee, or"],[1,"(ii) the person representing the claimant submits a written request to the Commissioner of Social Security to increase the maximum fee."],[0,"Any such review shall be conducted after providing the claimant, the person representing the claimant, and the adjudicator with reasonable notice of such request and an opportunity to submit written information in favor of or in opposition to such request. The adjudicator may request the Commissioner of Social Security to reduce the maximum fee only on the basis of evidence of the failure of the person representing the claimant to represent adequately the claimant's interest or on the basis of evidence that the fee is clearly excessive for services rendered."],[0,"(B)(i) In the case of a request for review under subparagraph (A) by the claimant or by the person representing the claimant, such review shall be conducted by the administrative law judge who made the favorable determination or, if the Commissioner of Social Security determines that such administrative law judge is unavailable or if the determination was not made by an administrative law judge, such review shall be conducted by another person designated by the Commissioner of Social Security for such purpose."],[0,"(ii) In the case of a request by the adjudicator for review under subparagraph (A), the review shall be conducted by the Commissioner of Social Security or by an administrative law judge or other person (other than such adjudicator) who is designated by the Commissioner of Social Security."],[0,"(C) Upon completion of the review, the administrative law judge or other person conducting the review shall affirm or modify the amount which would otherwise be the maximum fee. Any such amount so affirmed or modified shall be considered the amount of the maximum fee which may be recovered under paragraph (2). The decision of the administrative law judge or other person conducting the review shall not be subject to further review."],[0,"(4) Subject to subsection (d), if the claimant is determined to be entitled to past-due benefits under this subchapter and the person representing the claimant is an attorney, the Commissioner of Social Security shall, notwithstanding section 405(i) of this title, certify for payment out of such past-due benefits (as determined before any applicable reduction under section 1320a–6(a) of this title) to such attorney an amount equal to so much of the maximum fee as does not exceed 25 percent of such past-due benefits (as determined before any applicable reduction under section 1320a–6(a) of this title)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/406?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, passim, 2, 13, 2, 14, passim, 3, 7, 8","1":"21, 21, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2","2":"17, 18, 19, 7, 2, 10, 22, 7"},"q":[{"src":"brief","b":0,"text":"fix * * * a reasonable fee to compensate [the] attorney for the services performed by him in connection with such claim.","cite":"42 U.S.C. § 406(a)(1)"},{"src":"brief","b":0,"text":"[w]henever a court renders a judgment favorable to a claimant * * * who was represented before the court by an attorney.","cite":"42 U.S.C. § 406(b)(1)(A)"},{"src":"brief","b":1,"text":"[t]he Commissioner of Social Security may, by rule and regulation, prescribe the maximum fees which may be charged for services performed in connection with any [Title II] claim before the Commissioner.","cite":"42 U.S.C. 406(a)(1)"},{"src":"brief","b":1,"text":"prior to the time of the Commissioner’s determination.","cite":"42 U.S.C. 406(a)(2)(A)"},{"src":"brief","b":2,"text":"a reasonable [attorney’s] fee * * * not in excess of 25 percent of the total of the past-due benefits to which the claimant is entitled by reason of such judgment.","cite":"42 U.S.C. § 406(b)(1)(A)"},{"src":"brief","b":2,"text":"so much of the maximum fee as does not exceed 25 percent","cite":"42 U.S.C. § 406(a)(4)"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"a reasonable fee for such representation, not in excess of 25 percent of the total of the past-due benefits to which the claimant is entitled by reason of such judgment.","cite":"42 U. S. C. §406(b)(1)(A)"},{"src":"argument","who":"Ms. Weil","text":"Chief Justice, and may it please the Court: Section 406 is not a model of clarity. It's a piecemeal statute that was enacted over a series of amendments over a course of 50 years."}]},{"t":"usc","label":"42 U.S.C. § 415","url":"https://www.law.cornell.edu/uscode/text/42/415","subs":["(i)"],"by":{"0":"24, 26"}},{"t":"law","label":"Pub. L. No. 99-80","url":"https://www.govinfo.gov/link/statute/99/186","by":{"0":"4, 13","2":"16"}},{"t":"reg","label":"20 C.F.R. § 404.1720","url":"https://www.ecfr.gov/current/title-20/section-404.1720","subs":["(d)"],"by":{"0":"14"}},{"t":"reg","label":"20 C.F.R. § 404.1725","url":"https://www.ecfr.gov/current/title-20/section-404.1725","subs":["(b)(1)","(b)(2)"],"by":{"0":"14, 2"},"q":[{"src":"brief","b":0,"text":"may authorize a fee even if no benefits are payable.","cite":"20 C.F.R. § 404.1725(b)(2)"},{"src":"brief","b":0,"text":"the amount of fee the representative requests.","cite":"20 C.F.R. § 404.1725(b)(1)"}]},{"t":"reg","label":"Maximum Dollar Limit in the Fee Agreement Process, 74 Fed. Reg. 6080","url":"https://www.govinfo.gov/link/fr/74/6080","by":{"0":"2, 7, 14","1":"4, 5"}},{"t":"case","label":"Bowen v. Galbreath","cite":"485 U.S. 74","y":1988,"id":"1987/86-1146","sc":1,"by":{"1":"2, 8"},"q":[{"src":"brief","b":1,"text":"provides old-age, survivor, and disability [OASDI] benefits to insured individuals irrespective of financial need.","cite":"485 U.S. 74, 75"},{"src":"brief","b":1,"text":"to financially needy individuals who are aged, blind, or disabled regardless of their insured status.","cite":"485 U.S. at 75"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"provides old-age, survivor, and disability benefits to insured individuals irrespective of financial need.","cite":"485 U. S. 74, 75"}]},{"t":"case","label":"Fogerty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"by":{"1":"24"}},{"t":"case","label":"Shalala v. Schaefer","cite":"509 U.S. 292","y":1993,"id":"1992/92-311","sc":1,"by":{"1":"7"},"q":[{"src":"brief","b":1,"text":"judgment reversing the Secretary’s denial of benefits.","cite":"509 U.S. 292, 299, 302"},{"src":"brief","b":1,"text":"effectively increase[] the portion of past-due benefits the successful Social Security claimant may where new, material evidence is adduced that was for good cause not presented before the agency.","cite":"509 U.S. 292, 297 n.2"}]},{"t":"case","label":"Sullivan v. Hudson","cite":"490 U.S. 877","y":1989,"id":"1988/88-616","sc":1,"by":{"1":"6, 7"}},{"t":"case","label":"Wrenn ex rel. Wrenn v. Astrue","cite":"525 F.3d 931","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/525/931/","by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"ensur[e] the attorney fee is reasonable.","cite":"525 F.3d 931, 938"}]},{"t":"usc","label":"5 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/5/504","subs":["(a)(1)"],"by":{"1":"6"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(b)","(g)"],"by":{"1":"2, 2, 5, 6, 7, 10"}},{"t":"usc","label":"42 U.S.C. § 423","url":"https://www.law.cornell.edu/uscode/text/42/423","subs":["(a)"],"by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1381","url":"https://www.law.cornell.edu/uscode/text/42/1381","by":{"1":"2, 3, 5, 17"}},{"t":"usc","label":"42 U.S.C. § 1382","url":"https://www.law.cornell.edu/uscode/text/42/1382","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1383","url":"https://www.law.cornell.edu/uscode/text/42/1383","subs":["(c)(1)","(c)(2)","(c)(3)","(d)(2)(A)","(d)(2)(B)"],"stext":{"head":"§1383. Procedure for payment of benefits","paras":[[0,"(a) Time, manner, form, and duration of payments; representative payees; promulgation of regulations"],[0,"(1) Benefits under this subchapter shall be paid at such time or times and (subject to paragraph (10)) in such installments as will best effectuate the purposes of this subchapter, as determined under regulations (and may in any case be paid less frequently than monthly where the amount of the monthly benefit would not exceed $10)."],[0,"(2)(A)(i) Payments of the benefit of any individual may be made to any such individual or to the eligible spouse (if any) of such individual or partly to each."],[0,"(ii)(I) Upon a determination by the Commissioner of Social Security that the interest of such individual would be served thereby, such payments shall be made, regardless of the legal competency or incompetency of the individual or eligible spouse, to another individual, or an organization, with respect to whom the requirements of subparagraph (B) have been met (in this paragraph referred to as such individual's \"representative payee\") for the use and benefit of the individual or eligible spouse."],[0,"(II) In the case of an individual eligible for benefits under this subchapter by reason of disability, the payment of such benefits shall be made to a representative payee if the Commissioner of Social Security determines that such payment would serve the interest of the individual because the individual also has an alcoholism or drug addiction condition (as determined by the Commissioner) and the individual is incapable of managing such benefits."],[0,"(iii) If the Commissioner of Social Security or a court of competent jurisdiction determines that the representative payee of an individual or eligible spouse has misused any benefits which have been paid to the representative payee pursuant to clause (ii) or section 405(j)(1) or 1007 of this title, the Commissioner of Social Security shall promptly terminate payment of benefits to the representative payee pursuant to this subparagraph, and provide for payment of benefits to an alternative representative payee of the individual or eligible spouse or, if the interest of the individual under this subchapter would be served thereby, to the individual or eligible spouse."],[0,"(iv) For purposes of this paragraph, misuse of benefits by a representative payee occurs in any case in which the representative payee receives payment under this subchapter for the use and benefit of another person and converts such payment, or any part thereof, to a use other than for the use and benefit of such other person. The Commissioner of Social Security may prescribe by regulation the meaning of the term \"use and benefit\" for purposes of this clause."],[0,"(B)(i) Any determination made under subparagraph (A) for payment of benefits to the representative payee of an individual or eligible spouse shall be made on the basis of—"],[1,"(I) an investigation by the Commissioner of Social Security of the person to serve as representative payee, which shall be conducted in advance of such payment, and shall, to the extent practicable, include a face-to-face interview with such person; and"],[1,"(II) adequate evidence that such payment is in the interest of the individual or eligible spouse (as determined by the Commissioner of Social Security in regulations)."],[0,"(ii) As part of the investigation referred to in clause (i)(I), the Commissioner of Social Security shall—"],[1,"(I) require the person being investigated to submit documented proof of the identity of such person, unless information establishing such identity was submitted with an application for benefits under subchapter II, subchapter VIII, or this subchapter;"],[1,"(II) verify the social security account number (or employer identification number) of such person;"],[1,"(III) determine whether such person has been convicted of a violation of section 408, 1011, or 1383a of this title;"],[1,"(IV) obtain information concerning whether the person has been convicted of any other offense under Federal or State law which resulted in imprisonment for more than 1 year;"],[1,"(V) obtain information concerning whether such person is a person described in section 1382(e)(4)(A) of this title;"],[1,"(VI) determine whether payment of benefits to such person has been terminated pursuant to subparagraph (A)(iii), whether the designation of such person as a representative payee has been revoked pursuant to section 1007(a) of this title, and whether certification of payment of benefits to such person has been revoked pursuant to section 405(j) of this title, by reason of misuse of funds paid as benefits under subchapter II, subchapter VIII, or this subchapter, and"],[1,"(VII) determine whether such person has been convicted (and not subsequently exonerated), under Federal or State law, of a felony provided under clause (xv), or of an attempt or a conspiracy to commit such a felony."],[0,"(iii) Benefits of an individual may not be paid to any other person pursuant to subparagraph (A)(ii) if—"],[1,"(I) such person has previously been convicted as described in clause (ii)(III);"],[1,"(II) except as provided in clause (iv), payment of benefits to such person pursuant to subparagraph (A)(ii) has previously been terminated as described in clause (ii)(VI), the designation of such person as a representative payee has been revoked pursuant to section 1007(a) of this title, or certification of payment of benefits to such person under section 405(j) of this title has previously been revoked as described in section 405(j)(2)(B)(i)(VI) of this title;"],[1,"(III) except as provided in clause (v), such person is a creditor of such individual who provides such individual with goods or services for consideration;"],[1,"(IV) the person has previously been convicted as described in clause (ii)(IV) of this subparagraph, unless the Commissioner determines that the payment would be appropriate notwithstanding the conviction;"],[1,"(V) such person is a person described in section 1382(e)(4)(A) of this title,"],[1,"(VI) except as provided in clause (xvii), such person has previously been convicted (and not subsequently exonerated) as described in clause (ii)(VII), or"],[1,"(VII) such person's benefits under this subchapter, subchapter II, or subchapter VIII are certified for payment to a representative payee during the period for which the individual's benefits would be certified for payment to another person."],[0,"(iv) The Commissioner of Social Security shall prescribe regulations under which the Commissioner of Social Security may grant an exemption from clause (iii)(II) to any person on a case-by-case basis if such exemption would be in the best interest of the individual or eligible spouse whose benefits under this subchapter would be paid to such person pursuant to subparagraph (A)(ii)."],[0,"(v) Clause (iii)(III) shall not apply with respect to any person who is a creditor referred to therein if such creditor is—"],[1,"(I) a relative of such individual if such relative resides in the same household as such individual;"],[1,"(II) a legal guardian or legal representative of such individual;"],[1,"(III) a facility that is licensed or certified as a care facility under the law of a State or a political subdivision of a State;"],[1,"(IV) a person who is an administrator, owner, or employee of a facility referred to in subclause (III) if such individual resides in such facility, and the payment of benefits under this subchapter to such facility or such person is made only after good faith efforts have been made by the local servicing office of the Social Security Administration to locate an alternative representative payee to whom the payment of such benefits would serve the best interests of such individual; or"],[1,"(V) an individual who is determined by the Commissioner of Social Security, on the basis of written findings and under procedures which the Commissioner of Social Security shall prescribe by regulation, to be acceptable to serve as a representative payee."],[0,"(vi) The procedures referred to in clause (v)(V) shall require the individual who will serve as representative payee to establish, to the satisfaction of the Commissioner of Social Security, that—"],[1,"(I) such individual poses no risk to the beneficiary;"],[1,"(II) the financial relationship of such individual to the beneficiary poses no substantial conflict of interest; and"],[1,"(III) no other more suitable representative payee can be found."],[0,"(vii) In the case of an individual described in subparagraph (A)(ii)(II), when selecting such individual's representative payee, preference shall be given to—"],[1,"(I) a certified community-based nonprofit social service agency (as defined in subparagraph (I));"],[1,"(II) a Federal, State, or local government agency whose mission is to carry out income maintenance, social service, or health care-related activities;"],[1,"(III) a State or local government agency with fiduciary responsibilities; or"],[1,"(IV) a designee of an agency (other than of a Federal agency) referred to in the preceding subclauses of this clause, if the Commissioner of Social Security deems it appropriate,"],[0,"unless the Commissioner of Social Security determines that selection of a family member would be appropriate."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1383?type=usc&year=mostrecent&link-type=html"},"by":{"1":"2, 2, 2, 3, 3"},"q":[{"src":"brief","b":1,"text":"the Commissioner shall * * * fix * * * a reasonable fee to compensate such attorney for the services performed by him in connection with such claim.","cite":"42 U.S.C. 1383(d)(2)(A)"}]},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"2":"4"},"q":[{"src":"brief","b":2,"text":"Congress * * * has made only isolated amendments[, i]t is impossible to assert with any degree of assurance that congressional failure to act represents affirmative congressional approval of the [courts’] statutory interpretation.","cite":"532 U.S. 275, 292"}]},{"t":"case","label":"Astrue v. Ratliff","cite":"560 U.S. 586","y":2010,"id":"2009/08-1322","sc":1,"by":{"2":"16, 17"}},{"t":"case","label":"Bailey v. Heckler","cite":"621 F. Supp. 521","y":1985,"court":"W.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./621/521/","by":{"2":"10"}},{"t":"case","label":"Barnhart v. Walton","cite":"535 U.S. 212","y":2002,"id":"2001/00-1937","sc":1,"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"[s]ilence * * * normally creates ambiguity. It does not resolve it.","cite":"535 U.S. 212, 218"}]},{"t":"case","label":"BedRoc Ltd., LLC v. United States","cite":"541 U.S. 176","y":2004,"id":"2003/02-1593","sc":1,"by":{"2":"22"}},{"t":"case","label":"Brown v. Gardner","cite":"387 F.2d 345","y":1967,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/387/345/","by":{"2":"10"}},{"t":"case","label":"Claypool v. Barnhart","cite":"294 F. Supp. 2d 829","y":2003,"court":"S.D.W. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/294/829/","by":{"2":"14-15"}},{"t":"case","label":"Demarest v. Manspeaker","cite":"498 U.S. 184","y":1991,"id":"1990/89-5916","sc":1,"by":{"2":"3"}},{"t":"case","label":"Dig. Realty Tr., Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"corroborate[s] and fortif[ies the proper] understanding of the text.","cite":"138 S. Ct. 767, 783"}]},{"t":"case","label":"Horenstein v. Sec’y of Health & Human Servs.","cite":"35 F.3d 261","y":1994,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/35/261/","by":{"2":"3, 12"},"q":[{"src":"brief","b":2,"text":"set different statutory maximum allowable fees,","cite":"35 F.3d 261"},{"src":"argument","who":"Ms. Weil","text":"The Horenstein case that they cite in their brief about saying set different statutory maximum allowable fees in (a) and (b) was talking about this single tribunal rule."},{"src":"argument","who":"Mr. Ortiz","text":"And, finally, in Horenstein, although that was primarily a single tribunal case, the Sixth Circuit en banc made clear that the single tribunal rule and the aggregate cap rule had to stand or fall together."}]},{"t":"case","label":"Lavender v. Califano","cite":"683 F.2d 133","y":1982,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/683/133/","by":{"2":"10"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"2":"4"},"q":[{"src":"brief","b":2,"text":"Congress is presumed to be aware of an administrative or judicial interpretation of a statute and to adopt that interpretation when it re-enacts a statute without change.","cite":"434 U.S. 575, 580"}]},{"t":"case","label":"Melvin v. Colvin","cite":"2013 WL 3340490","y":2013,"court":"E.D.N.C. July 2","by":{"2":"14"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"by":{"2":"22"},"q":[{"src":"brief","b":2,"text":"our inquiry beg[a]n[ ] with the statutory text, [it] ends there as well.","cite":"138 S. Ct. 617, 631"},{"src":"brief","b":2,"text":"Rather than confront that statutory text, [amicus] asks [this Court] to ignore it altogether.","cite":"138 S. Ct. at 631"}]},{"t":"case","label":"Pierce v. Underwood","cite":"487 U.S. 552","y":1988,"id":"1987/86-1512","sc":1,"by":{"2":"16, 17"},"q":[{"src":"brief","b":2,"text":"the generality rather than the exception must form the basis for [a] rule.","cite":"487 U.S. 552, 563"},{"src":"brief","b":2,"text":"the lawyer will rarely be able to assess with any degree of certainty the likelihood that the Government’s position will be deemed so unreasonable as to produce an EAJA award.","cite":"487 U.S. at 573"}]},{"t":"case","label":"Pub. Emps. Ret. Sys. of Ohio v. Betts","cite":"492 U.S. 158","y":1989,"id":"1988/88-389","sc":1,"by":{"2":"12"},"q":[{"src":"brief","b":2,"text":"[N]o deference is due to agency interpretations at odds with the plain language of the statute itself.","cite":"492 U.S. 158, 171"}]},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"by":{"2":"6"},"q":[{"src":"brief","b":2,"text":"it frustrates rather than effectuates legislative intent simplistically to assume that whatever furthers the statute’s primary objective must be the law.","cite":"480 U.S. 522, 526"}]},{"t":"case","label":"Sabourin v. Colvin","cite":"2014 WL 3949506","y":2014,"court":"N.D. Tex. Aug. 12","by":{"2":"14"}},{"t":"case","label":"Salinger v. Loisel","cite":"265 U.S. 224","y":1924,"id":"scdb/1923-152","sc":1,"by":{"2":"9"}},{"t":"case","label":"Vilkas v. Comm’r of Soc. Sec.","cite":"2007 WL 1498115","y":2007,"court":"M.D. Fla. May 14","by":{"2":"14"}},{"t":"case","label":"Wells v. Sullivan","cite":"907 F.2d 367","y":1990,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/907/367/","by":{"2":"16"}},{"t":"usc","label":"42 U.S.C. § 407","url":"https://www.law.cornell.edu/uscode/text/42/407","subs":["(a)"],"stext":{"head":"§407. Assignment of benefits","paras":[[0,"(a) In general"],[0,"The right of any person to any future payment under this subchapter shall not be transferable or assignable, at law or in equity, and none of the moneys paid or payable or rights existing under this subchapter shall be subject to execution, levy, attachment, garnishment, or other legal process, or to the operation of any bankruptcy or insolvency law."],[0,"(b) Amendment of section"],[0,"No other provision of law, enacted before, on, or after April 20, 1983, may be construed to limit, supersede, or otherwise modify the provisions of this section except to the extent that it does so by express reference to this section."],[0,"(c) Withholding of taxes"],[0,"Nothing in this section shall be construed to prohibit withholding taxes from any benefit under this subchapter, if such withholding is done pursuant to a request made in accordance with section 3402(p)(1) of the Internal Revenue Code of 1986 by the person entitled to such benefit or such person's representative payee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/407?type=usc&year=mostrecent&link-type=html"},"by":{"2":"20"},"q":[{"src":"brief","b":2,"text":"execution, levy, attachment, garnishment, or other legal process, or to the operation of any bankruptcy or insolvency law.","cite":"42 U.S.C. § 407(a)"}]},{"t":"law","label":"Pub. L. No. 101-508","url":"https://www.govinfo.gov/link/statute/104/1388","by":{"2":"4"}},{"t":"reg","label":"20 C.F.R. § 404.1820","url":"https://www.ecfr.gov/current/title-20/section-404.1820","subs":["(a)(2)"],"by":{"2":"20"}}]};